/* Energie-Monitor 1.0.1 – Ein-Datei-Update.
   Diese Datei ersetzt sw.js im Hauptverzeichnis.
   Enthält die aktualisierte Oberfläche und CSS, damit kein weiterer Upload
   erforderlich ist. Keine Messwerte enthalten; IndexedDB bleibt unverändert.
   Nach Bereitstellung App mit Internet öffnen, vollständig schließen und erneut öffnen.
   Bei späteren Updates die eingebetteten Ressourcen ebenfalls aktualisieren oder
   wieder auf eine normale Mehrdatei-Bereitstellung mit neuer Cache-Version wechseln.
*/
const VERSION='energie-v1.0.1';
const PREFIX='energie:'+self.registration.scope+':';
const CACHE=PREFIX+VERSION;
const FILES=['./','./index.html','./core.js','./storage.js','./io.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest','./vendor/exceljs.min.js'];
const UPDATED_APP="import * as C from './core.js';\nimport {readState,commit} from './storage.js';\nimport * as IO from './io.js';\nconst $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];\nconst esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst fmt=(v,d=3)=>v==null?'—':new Intl.NumberFormat('de-DE',{maximumFractionDigits:d}).format(v);\nconst inp=v=>v==null?'':String(v).replace('.',',');\nconst opts=(items,selected)=>items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value=\"${esc(v)}\" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`}).join('');\nlet state,tab='home',dirty=false,editing=C.lastMonth(),editBase=null,year=String(new Date().getFullYear()),analysis='trend',metric='pv',yearB=String(+year-1),calendarMonth=+C.lastMonth().slice(5),pending=null,importData=null,backupURL=null,swStatus='Offline-Einrichtung wird geprüft …';\nlet rows=[],chartSeq=0,toastTimer;\nconst navs=[['home','Übersicht','M3 11 12 3l9 8v10h-6v-7H9v7H3z'],['entry','Erfassen','M12 5v14M5 12h14'],['history','Verlauf','M4 4h16v17H4zM8 8h8M8 12h8M8 16h5'],['compare','Vergleich','M5 20V10M12 20V4M19 20v-7'],['backup','Sichern','M5 4h12l3 3v14H4V4zM8 4v6h8V4M8 21v-7h8v7']];\nfunction notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500)}\nfunction error(e){const target=$('#form-error')||$('#import-error')||$('#global-error');if(target){target.hidden=false;target.textContent=e.message||String(e);target.scrollIntoView({block:'nearest'})}else notify(e.message||String(e))}\nconst years=()=>[...new Set([...state.records.map(r=>r.month.slice(0,4)),String(new Date().getFullYear())])].sort().reverse();\nconst annualRows=()=>rows.filter(r=>r.month.startsWith(year));\nfunction head(title,sub,control=''){return `<div class=\"pagehead\"><div><div class=\"eyebrow\">Deine Energie. Im Blick.</div><h1>${title}</h1><p>${sub}</p></div>${control}</div><div id=\"global-error\" class=\"warn error\" hidden></div>`}\nconst yearControl=()=>`<label>Jahr<select id=\"year\">${opts(years(),year)}</select></label>`;\nconst empty=()=>`<div class=\"card empty\"><div class=\"seal\">↗</div><h2>Ein guter Anfang.</h2><p>Importiere deine bisherigen Werte oder erfasse den ersten Monat.<br>Alles bleibt auf diesem Gerät.</p><div class=\"row\" style=\"justify-content:center\"><button class=\"primary\" data-nav=\"entry\">Monat erfassen</button><button data-nav=\"backup\">Daten importieren</button></div></div>`;\nfunction metricCard(k,a,change){const m=C.METRICS[k];return `<div class=\"card metric\" style=\"--color:${m[2]}\"><div class=\"name\">${m[0]}</div><div class=\"value\">${fmt(a.value,k==='autarky'||k==='ratio'?1:2)} <span class=\"unit\">${m[1]}</span></div><small>${a.count}/12 Monate${a.estimated?' · ≈ enthält Schätzungen':''}</small>${change&&change.months.length?`<div class=\"muted\">${change.delta>0?'+':''}${fmt(change.delta,1)} ${['autarky','ratio'].includes(k)?'Prozentpunkte':m[1]} zum Vorjahr${change.percent!=null?` (${change.percent>0?'+':''}${fmt(change.percent,1)} %)` :''}<br>${change.months.length} gleiche Kalendermonate</div>`:''}</div>`}\nfunction home(){const ar=annualRows(),aut=C.aggregate(ar,'autarky'),total=C.aggregate(ar,'total'),last=rows.at(-1);return head('Energie verstehen.','Dein Zuhause, in Zahlen.',yearControl())+(!rows.length?empty():`<section class=\"card hero\"><div class=\"eyebrow\">JAHRESBILANZ · ${year}</div><div class=\"split\"><div><h2>Dein Stromverbrauch</h2><div class=\"big\">${fmt(total.value,1)} <span>kWh</span></div><p style=\"margin:12px 0 0\">${total.count} auswertbare Monate${total.count<12?' · Jahr unvollständig':''}${total.estimated?' · ≈ mit Schätzungen':''}</p></div><div class=\"ring\" style=\"--percent:${aut.value??0}\"><div class=\"ring-inner\">${fmt(aut.value,1)} %<small>AUTARKIE · ${aut.count} MON.</small></div></div></div></section><div class=\"grid\">${['pv','grid','feed','self','gas','total','autarky','ratio'].map(k=>metricCard(k,C.aggregate(ar,k),C.compareYears(rows,year,+year-1,k))).join('')}</div><div class=\"section row between\"><h2>Zuletzt erfasst</h2><button data-edit=\"${last.month}\">${C.monthLabel(last.month)} bearbeiten ↗</button></div><p class=\"muted\">${last.missing.length?`Noch nicht berechenbar: ${last.missing.map(k=>C.METRICS[k][0]).join(', ')}.`:'Alle vier Monatsmengen sind verfügbar.'} ${last.month<C.lastMonth()?`Der zuletzt abgeschlossene Monat ist ${C.monthLabel(C.lastMonth())}.`:''}</p>${ar.some(r=>r.warnings.length)?`<details class=\"warn\"><summary>${ar.filter(r=>r.warnings.length).length} Monate mit Prüfhinweisen im Jahr ${year}</summary>${ar.filter(r=>r.warnings.length).map(r=>`<p><button class=\"linklike\" data-edit=\"${r.month}\">${C.monthLabel(r.month)}</button><br>${r.warnings.map(esc).join('<br>')}</p>`).join('')}</details>`:''}${[['pv','Erzeugung im Jahreslauf'],['grid','Netzbezug im Jahreslauf'],['total','Gesamtstrom im Jahreslauf'],['gas','Gasverbrauch im Jahreslauf']].map(([key,title])=>`<section class=\"card section annual-chart\"><div class=\"row between\"><h2>${title}</h2><span class=\"pill\">${C.METRICS[key][0]} · ${year}</span></div>${key==='total'?'<p class=\"muted\">Netzbezug und selbst genutzter PV-Strom zusammen.</p>':''}${chart(monthItems(year),[{key,label:C.METRICS[key][0],color:C.METRICS[key][2]}],C.METRICS[key][1])}</section>`).join('')}`)+backupReminder()}\nfunction backupReminder(){const last=state.settings.lastBackup;return !last||Date.now()-new Date(last)>Number(state.settings.backupDays||30)*864e5?`<div class=\"privacy\">${last?'Zeit für eine neue Sicherung.':'Deine Daten verdienen eine Sicherung.'} Browserspeicher kann gelöscht werden. <button class=\"linklike\" data-nav=\"backup\">JSON-Sicherung erstellen</button></div>`:''}\nfunction field(k,r){const a=r[k],m=C.METRICS[k],p=state.records.find(x=>x.month===C.prevMonth(r.month));const title={gas:'Gaszählerstand',grid:'Netzbezugszähler',feed:'Einspeisezähler',pv:'PV-Ertrag des Monats'}[k];return `<section class=\"card entry\" style=\"--color:${m[2]}\"><label class=\"main-label\" for=\"${k}-value\">${title} · ${m[1]}</label><input class=\"main-value\" id=\"${k}-value\" name=\"${k}-value\" inputmode=\"decimal\" autocomplete=\"off\" value=\"${inp(k==='pv'?a.amount:a.reading)}\" placeholder=\"Noch offen\"><small>${k==='pv'?'Gesamte Erzeugung des Monats':`Vormonat: ${fmt(p?.[k]?.reading)} ${m[1]}`}</small><div class=\"preview\" id=\"${k}-preview\"></div><details ${a.amount!=null&&k!=='pv'||a.reset?'open':''}><summary>Qualität${a.quality==='estimated'?' · ≈ geschätzt':''} & Details</summary><label>Datenqualität<select id=\"${k}-quality\">${opts([['measured','Gemessen / übernommen'],['estimated','≈ Geschätzt'],['check','⚠ Prüfen']],a.quality)}</select></label>${k!=='pv'?`<label>Direkte Monatsmenge · ${m[1]}<input id=\"${k}-amount\" inputmode=\"decimal\" value=\"${inp(a.amount)}\" placeholder=\"Optional\"></label><small>Für Archiv oder bekannten Monatsverbrauch. Hat Vorrang vor der Zählerdifferenz.</small><label class=\"checklabel\"><input type=\"checkbox\" id=\"${k}-reset\" ${a.reset?'checked':''}> Zählerwechsel / Rücksetzung</label><label>Alter Zähler: Endstand<input id=\"${k}-oldEnd\" inputmode=\"decimal\" value=\"${inp(a.reset?.oldEnd)}\"></label><label>Neuer Zähler: Anfangsstand<input id=\"${k}-newStart\" inputmode=\"decimal\" value=\"${inp(a.reset?.newStart)}\"></label>`:''}<label>Hinweis / Herkunft<textarea id=\"${k}-note\">${esc(a.note)}</textarea></label></details></section>`}\nfunction entry(){const r=C.clone(state.records.find(x=>x.month===editing)||C.emptyRecord(editing));editBase=r;const missing=olderGaps();return head('Monat erfassen.','Vier Werte. Ein klarer Überblick.')+`<section class=\"card\"><div class=\"month-picker\"><label>Monat auswählen<input id=\"pick-month\" type=\"month\" value=\"${editing}\" min=\"1900-01\"></label><button id=\"load-month\">Monat laden</button></div><p class=\"muted\" style=\"margin:14px 0 0\">Bearbeitet wird: <strong>${C.monthLabel(editing)}</strong> · ${state.records.some(x=>x.month===editing)?'Vorhandener Eintrag':'Neuer Eintrag'}<br>Standardvorschlag: zuletzt abgeschlossener Kalendermonat. Erst „Monat laden“ wechselt die Eingabe.</p>${missing.length?`<details class=\"warn\"><summary>${missing.length} frühere Monate fehlen vollständig</summary><p>${missing.map(C.monthLabel).join(', ')}</p></details>`:''}</section><form id=\"entry-form\" novalidate><div class=\"entry-grid\">${C.KEYS.map(k=>field(k,r)).join('')}</div><p class=\"muted\" style=\"margin-top:12px\">Ohne Tausendertrennzeichen eingeben. Dezimalkomma wird unterstützt. Mehrdeutige Punkt-Schreibweisen werden nachgefragt. Leere Felder bleiben unbekannt.</p><details class=\"card\"><summary>Ablesedatum & Monatsnotiz</summary><label>Ablesedatum (optional)<input type=\"date\" id=\"read-date\" value=\"${esc(r.readDate)}\"></label><label style=\"margin-top:16px\">Notiz<textarea id=\"month-note\">${esc(r.note)}</textarea></label>${r.source?`<small>Übernommene Quelle: ${esc(JSON.stringify(r.source))}</small>`:''}</details><div id=\"form-error\" role=\"alert\" class=\"warn error\" hidden></div><div id=\"entry-warnings\"></div><div class=\"form-actions\"><button class=\"primary\" type=\"submit\">Monat speichern</button><button type=\"button\" id=\"discard\">Neu laden</button></div><div class=\"row\"><button type=\"button\" id=\"draft\">Entwurf als JSON sichern</button>${state.records.some(x=>x.month===editing)?'<button type=\"button\" id=\"delete-month\" class=\"danger\">Monat löschen</button>':''}</div><p class=\"footer-note\">Änderungen an einem Zählerstand aktualisieren auch den Folgemonat. Bis zu 20 lokale Wiederherstellungspunkte unter „Sichern“.</p></form>`}\nfunction olderGaps(){if(!state.records.length)return [];const first=[...state.records].sort((a,b)=>a.month.localeCompare(b.month))[0].month;const out=[];let m=C.prevMonth(editing);for(let i=0;m>=first&&i<2400;i++,m=C.prevMonth(m))if(!state.records.some(r=>r.month===m))out.push(m);return out.reverse()}\nfunction gather(){const r=C.clone(editBase);for(const k of C.KEYS){try{r[k][k==='pv'?'amount':'reading']=C.parseNumber($(`#${k}-value`).value);r[k].quality=$(`#${k}-quality`).value;r[k].note=$(`#${k}-note`).value;if(k!=='pv'){r[k].amount=C.parseNumber($(`#${k}-amount`).value);if($(`#${k}-reset`).checked)r[k].reset={oldEnd:C.parseNumber($(`#${k}-oldEnd`).value),newStart:C.parseNumber($(`#${k}-newStart`).value)};if(k!=='pv'&&!$(`#${k}-reset`).checked)delete r[k].reset;} }catch(e){throw Error(`${C.METRICS[k][0]}: ${e.message}`)}}r.readDate=$('#read-date').value;r.note=$('#month-note').value;return C.validateRecord(r)}\nfunction updatePreview(){try{const r=gather(),all=C.calculate([...state.records.filter(x=>x.month!==editing),r]);const x=all.find(x=>x.month===editing);for(const k of C.KEYS)$(`#${k}-preview`).textContent=`${k==='pv'?'Monatsertrag':'Monatsmenge'}: ${fmt(x[k])} ${C.METRICS[k][1]}${x.estimated[k]?' ≈':''}`;const n=all.find(t=>C.prevMonth(t.month)===editing);$('#entry-warnings').innerHTML=(x.warnings.length?`<div class=\"warn\">${x.warnings.map(esc).join('<br>')}</div>`:'')+(n?`<p class=\"muted\">Vorschau Folgemonat ${C.monthLabel(n.month)}: ${['gas','grid','feed'].map(k=>`${C.METRICS[k][0]} ${fmt(n[k])} ${C.METRICS[k][1]}`).join(' · ')}</p>`:'');$('#form-error').hidden=true}catch(e){for(const k of C.KEYS)$(`#${k}-preview`).textContent='Eingabe prüfen';$('#form-error').hidden=false;$('#form-error').textContent=e.message}}\nfunction history(){return head('Dein Verlauf.','Jeder Monat bleibt bearbeitbar.',yearControl())+`<div class=\"card\"><label>Monat suchen<input id=\"history-search\" type=\"search\" placeholder=\"z. B. März oder 2025-03\"></label></div><div id=\"month-list\" class=\"month-list\">${historyList('')}</div>`}\nfunction historyList(search){const hits=rows.filter(r=>r.month.startsWith(year)&&(C.monthLabel(r.month)+' '+r.month).toLowerCase().includes(search.toLowerCase()));return hits.length?hits.slice().reverse().map(r=>`<button class=\"month-row\" data-edit=\"${r.month}\"><strong>${C.monthLabel(r.month)} <span style=\"float:right;color:#a78a50\">↗</span></strong><div class=\"sub\">PV ${fmt(r.pv,2)} kWh · Netz ${fmt(r.grid,2)} kWh<br>Gas ${fmt(r.gas)} m³ · Einspeisung ${fmt(r.feed,2)} kWh</div><div style=\"margin-top:10px\"><span class=\"pill\">${r.missing.length?`${r.missing.length} Monatsmengen offen`:'Vollständig'}</span> ${Object.values(r.estimated).some(Boolean)?'<span class=\"pill\">≈ Schätzanteil</span>':''} ${r.warnings.length?'<span class=\"pill\">⚠ Prüfen</span>':''}</div></button>`).join(''):'<div class=\"card\">Keine passenden Monate. <button data-nav=\"entry\">Monat erfassen</button></div>'}\nfunction monthItems(y){return Array.from({length:12},(_,i)=>{const m=`${y}-${String(i+1).padStart(2,'0')}`;return {label:C.MONTHS[i].slice(0,3),...(rows.find(r=>r.month===m)||{}),month:m}})}\nfunction chart(items,series,unit){const id=++chartSeq;const values=items.flatMap(x=>series.map(s=>x[s.key])).filter(x=>typeof x==='number'&&Number.isFinite(x));let min=Math.min(0,...values),max=Math.max(1,...values);if(min===max)max=min+1;const W=650,H=270,left=55,right=10,top=18,bottom=37;const ph=H-top-bottom,pw=W-left-right;const y=v=>top+(max-v)/(max-min)*ph;const base=y(0),bw=pw/Math.max(1,items.length);let svg=`<svg class=\"chart\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Diagramm in ${unit}. Genaue Werte stehen in der Tabellenansicht.\"><defs><pattern id=\"hatch${id}\" width=\"5\" height=\"5\" patternUnits=\"userSpaceOnUse\"><path d=\"M0 5 5 0\" stroke=\"#fff\" stroke-width=\"1.5\" opacity=\".8\"/></pattern></defs>`;for(let t=0;t<4;t++){const v=min+(max-min)*t/3;svg+=`<line x1=\"${left}\" x2=\"${W-right}\" y1=\"${y(v)}\" y2=\"${y(v)}\" stroke=\"#e2e4dc\"/><text x=\"${left-7}\" y=\"${y(v)+4}\" text-anchor=\"end\">${fmt(v,0)}</text>`}svg+=`<text x=\"${left}\" y=\"12\">${unit}</text>`;items.forEach((item,i)=>{series.forEach((s,j)=>{const value=item[s.key];const x=left+i*bw+bw*.16+j*bw*.68/series.length;const width=bw*.68/series.length-1;const est=item.estimated?.[s.key];const tip=`${item.month?C.monthLabel(item.month):item.label} · ${s.label}: ${fmt(value,6)} ${unit}${est?' · ≈ Schätzung / schätzabhängig':''}`;if(value==null)svg+=`<text x=\"${x+width/2}\" y=\"${base-5}\" text-anchor=\"middle\">·</text>`;else{const yy=Math.min(base,y(value)),height=Math.max(2,Math.abs(base-y(value)));svg+=`<g tabindex=\"0\" role=\"button\" aria-label=\"${esc(tip)}\" data-tip=\"${esc(tip)}\"><rect x=\"${x}\" y=\"${yy}\" width=\"${Math.max(1,width)}\" height=\"${height}\" rx=\"2\" fill=\"${s.color}\"/>${est?`<rect x=\"${x}\" y=\"${yy}\" width=\"${Math.max(1,width)}\" height=\"${height}\" fill=\"url(#hatch${id})\"/>`:''}<title>${esc(tip)}</title></g>`}});svg+=`<text x=\"${left+(i+.5)*bw}\" y=\"${H-14}\" text-anchor=\"middle\">${esc(item.label)}</text>`});svg+='</svg>';return `<div class=\"chart-wrap\"><div class=\"legend\">${series.map(s=>`<span><i class=\"dot\" style=\"--color:${s.color}\"></i>${esc(s.label)}</span>`).join('')}<span>≈ Schätzung: schraffiert · fehlend: Punkt</span></div>${svg}<div class=\"chart-value\" aria-live=\"polite\">Balken antippen für den genauen Wert.</div><details><summary>Genaue Werte als Tabelle</summary><div class=\"data-table\" role=\"table\" aria-label=\"Diagrammdaten\">${items.map(x=>`<div class=\"data-row\" role=\"row\"><span role=\"cell\">${esc(x.month?C.monthLabel(x.month):x.label)}</span><span role=\"cell\">${series.map(s=>`${esc(s.label)}: ${fmt(x[s.key],6)} ${unit}${x.estimated?.[s.key]?' ≈':''}`).join('<br>')}</span></div>`).join('')}</div></details></div>`}\nfunction compare(){const options=[['trend','Monatlicher Verlauf'],['balance','PV, Einspeisung & Eigenverbrauch'],['supply','Stromverbrauch: Netz & PV'],['rates','Autarkie & Eigenverbrauchsquote'],['month','Kalendermonat über alle Jahre'],['two','Zwei Jahre vergleichen'],['years','Jahreswerte im Vergleich'],['heat','Jahresübersicht / Heatmap']];let items,series,unit=C.METRICS[metric][1],desc='',ar=annualRows();\n if(['trend','balance','supply','rates','heat'].includes(analysis)){items=monthItems(year);const keys=analysis==='balance'?['pv','feed','self']:analysis==='supply'?['grid','self','total']:analysis==='rates'?['autarky','ratio']:[metric];series=keys.map(k=>({key:k,label:C.METRICS[k][0],color:C.METRICS[k][2]}));unit=analysis==='rates'?'%':analysis==='balance'||analysis==='supply'?'kWh':unit;desc=`${year} · Fehlende Monate bleiben offen.`}\n if(analysis==='month'){items=years().slice().reverse().map(y=>{const month=`${y}-${String(calendarMonth).padStart(2,'0')}`;return {label:y,...rows.find(r=>r.month===month),month}});series=[{key:metric,label:C.METRICS[metric][0],color:C.METRICS[metric][2]}];desc=`${C.MONTHS[calendarMonth-1]} in allen Jahren`}\n if(analysis==='two'){items=C.MONTHS.map((m,i)=>{const a=rows.find(r=>r.month===`${year}-${String(i+1).padStart(2,'0')}`),b=rows.find(r=>r.month===`${yearB}-${String(i+1).padStart(2,'0')}`);return {label:m.slice(0,3),a:a?.[metric]??null,b:b?.[metric]??null,estimated:{a:a?.estimated[metric],b:b?.estimated[metric]}}});series=[{key:'a',label:year,color:C.METRICS[metric][2]},{key:'b',label:yearB,color:'#b59c6d'}];const c=C.compareYears(rows,year,yearB,metric);desc=`${c.months.length} gemeinsame Kalendermonate: ${c.months.map(m=>C.MONTHS[+m-1].slice(0,3)).join(', ')||'keine'}. Veränderung ${fmt(c.delta,2)} ${['autarky','ratio'].includes(metric)?'Prozentpunkte':unit}${c.percent!=null?` (${fmt(c.percent,1)} %)`:''}.`}\n if(analysis==='years'){items=years().slice().reverse().map(y=>{const a=C.aggregate(rows.filter(r=>r.month.startsWith(y)),metric);return {label:`${y} (${a.count}/12)`,[metric]:a.value,estimated:{[metric]:a.estimated}}});series=[{key:metric,label:C.METRICS[metric][0],color:C.METRICS[metric][2]}];desc='Jahressummen beziehungsweise mengenbasierte Quoten. Unvollständige Jahre sind nur bedingt vergleichbar.'}\n const values=ar.filter(r=>r[metric]!=null).sort((a,b)=>a[metric]-b[metric]);return head('Muster entdecken.','Vergleiche, die Zusammenhänge zeigen.')+`<section class=\"card\"><div class=\"controls\"><label>Auswertung<select id=\"analysis\">${opts(options,analysis)}</select></label><label>Kennzahl<select id=\"metric\">${opts(Object.entries(C.METRICS).map(([k,m])=>[k,`${m[0]} · ${m[1]}`]),metric)}</select></label><label>Jahr A<select id=\"year\">${opts(years(),year)}</select></label>${analysis==='two'?`<label>Jahr B<select id=\"year-b\">${opts(years(),yearB)}</select></label>`:''}${analysis==='month'?`<label>Kalendermonat<select id=\"calendar-month\">${opts(C.MONTHS.map((m,i)=>[i+1,m]),calendarMonth)}</select></label>`:''}</div><h2>${options.find(o=>o[0]===analysis)[1]}</h2><p class=\"muted\">${esc(desc)}</p>${analysis==='heat'?`<div class=\"heatmap\">${items.map(r=>{const max=Math.max(1,...items.map(x=>Math.abs(x[metric]||0)));return `<div class=\"heat-cell\" style=\"background:rgba(55,117,87,${r[metric]==null?0:.07+.3*Math.abs(r[metric])/max})\">${r.label}<strong>${fmt(r[metric],2)} <small>${unit}</small></strong>${r.estimated?.[metric]?'≈ geschätzt':''}</div>`}).join('')}</div>`:chart(items,series,unit)}</section><section class=\"card\"><h2>${C.METRICS[metric][0]} · ${year}</h2>${values.length?`<div class=\"data-row\"><span>Höchster Monat</span><span>${C.monthLabel(values.at(-1).month)} · ${fmt(values.at(-1)[metric])} ${C.METRICS[metric][1]}</span></div><div class=\"data-row\"><span>Niedrigster Monat</span><span>${C.monthLabel(values[0].month)} · ${fmt(values[0][metric])} ${C.METRICS[metric][1]}</span></div><div class=\"data-row\"><span>${['autarky','ratio'].includes(metric)?'Mengenbasierte Jahresquote':'Durchschnitt pro vorhandenem Monat'}</span><span>${fmt(['autarky','ratio'].includes(metric)?C.aggregate(ar,metric).value:values.reduce((s,r)=>s+r[metric],0)/values.length)} ${C.METRICS[metric][1]}<br>${values.length} Monate Datenbasis</span></div>`:'<p>Noch keine auswertbaren Monatswerte.</p>'}<p class=\"footer-note\">≈ kennzeichnet Schätzungen und davon abhängige Differenzen. Gas bleibt in m³. Quoten beziehen sich auf die jeweils gemeinsam berechenbaren Energiemengen; Summen einzelner Kennzahlen können unterschiedliche Datenbasen haben.</p></section>`}\nfunction backup(){return head('Sichern & bewahren.','Deine Daten bleiben in deiner Hand.')+`<section class=\"card\"><h2>Eine Kopie für dich.</h2><p class=\"muted\">JSON sichert den vollständigen App-Bestand. Excel und CSV sind für Auswertung und Weitergabe.</p><div class=\"row\"><label class=\"grow\">Auswertung ab (optional)<input id=\"export-from\" type=\"month\"></label><label class=\"grow\">Auswertung bis (optional)<input id=\"export-to\" type=\"month\"></label></div><div class=\"backup-actions section\"><button data-export=\"json\" class=\"primary\"><strong>JSON</strong><small>Vollständige Sicherung<br>Alle Monate, Einstellungen & Historie</small></button><button data-export=\"xlsx\"><strong>Excel</strong><small>Formatierte Arbeitsmappe<br>Rohwerte, Auswertung & Jahresbilanz</small></button><button data-export=\"csv\"><strong>CSV</strong><small>Universelle Tabelle<br>UTF-8, Semikolon & Dezimalkomma</small></button></div><div id=\"download-area\"></div><p class=\"footer-note\">Letzte bereitgestellte JSON-Sicherung: ${state.settings.lastBackup?new Date(state.settings.lastBackup).toLocaleString('de-DE'):'noch keine'}. Bitte kontrolliere, ob du sie tatsächlich gespeichert hast.</p></section><section class=\"card\"><h2>Daten importieren</h2><p class=\"muted\">Dateien werden ausschließlich auf diesem Gerät gelesen. Vor jeder Übernahme siehst du eine Vorschau. Bis dahin wird nichts geändert.</p><label>Datei auswählen · XLSX, CSV oder JSON<input id=\"import-file\" type=\"file\" accept=\".xlsx,.csv,.json,application/json,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\"></label><div id=\"import-error\" class=\"warn error\" hidden role=\"alert\"></div><div id=\"import-area\"></div></section><section class=\"card\"><h2>Wiederherstellen</h2><p class=\"muted\">Die letzten 20 Änderungen haben einen lokalen Wiederherstellungspunkt. Dieser ersetzt keine externe Sicherungsdatei.</p>${state.history.length?state.history.slice(0,20).map((h,i)=>`<div class=\"data-row\"><span>${esc(h.label)}<br><small>${new Date(h.at).toLocaleString('de-DE')}</small></span><button data-restore=\"${i}\">Stand davor</button></div>`).join(''):'<p class=\"muted\">Noch keine Änderungen gespeichert.</p>'}</section><section class=\"card\"><h2>Auf diesem Gerät</h2><p class=\"privacy\">Messwerte, Notizen und Importe werden in IndexedDB lokal gespeichert. Die App sendet sie nicht an den Webserver. Es gibt keine Anmeldung, Analyse-Dienste oder Cloud-Synchronisierung. Ein anderes Gerät hat einen eigenen Datenbestand.</p><p>Browserspeicher kann durch das Löschen von Website-Daten, Speicherbereinigung oder Geräteverlust verloren gehen. Auch angeforderter dauerhafter Speicher ist keine Garantie. Sichere regelmäßig eine JSON-Datei.</p><div class=\"row\"><label class=\"grow\">Sicherungshinweis nach Tagen<input id=\"backup-days\" inputmode=\"numeric\" type=\"number\" min=\"1\" max=\"365\" value=\"${state.settings.backupDays||30}\"></label><button id=\"save-settings\">Einstellung speichern</button></div><div class=\"row section\"><button id=\"persist\">Dauerhaften Speicher anfragen</button><button id=\"check-update\">Nach App-Update suchen</button></div><p class=\"status-line section\" id=\"offline-status\">${esc(swStatus)}</p><p class=\"status-line\">Version ${\"1.0.1\"} · ${state.records.length} Monate · Revision ${state.revision}</p><details><summary>Installation, Sicherung & Datenschutz</summary><p>1. Das Upload-Paket auf einen HTTPS-Webspace entpacken. Private Importdateien gehören niemals auf den Webserver.<br>2. In Safari öffnen, unter „Sichern“ auf die Offline-Bereitschaft warten.<br>3. Teilen → Zum Home-Bildschirm → Hinzufügen. Die App vom Home-Bildschirm starten und hier den privaten Bestand importieren.<br>4. Für Sicherungen zuerst Export erstellen, dann „Teilen / in Dateien sichern“ → In Dateien sichern → Auf meinem iPhone. Einen lokalen Ordner wählen. Kein iCloud-Drive-Ziel auswählen, wenn die Datei lokal bleiben soll.<br>5. Nach Updates Domain und Unterverzeichnis unverändert lassen. Erst JSON sichern, dann App-Dateien ersetzen und alle App-Fenster schließen und neu öffnen.<br><br>Das Betriebssystem oder deine Gerätesicherung kann eigene Sicherungsregeln haben. Die App selbst synchronisiert keine Messwerte. Hosting-Zugriffe auf öffentliche App-Dateien können in Server-Logs erscheinen, enthalten aber keine von der App gesendeten Messwerte.</p></details></section>`}\nfunction render(){rows=C.calculate(state.records);$('#nav').innerHTML=navs.map(([id,label,path])=>`<button data-nav=\"${id}\" class=\"${tab===id?'active':''}\" ${tab===id?'aria-current=\"page\"':''}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"${path}\"/></svg>${label}</button>`).join('');$('#app').innerHTML=({home,entry,history,compare,backup})[tab]();if(tab==='entry'){updatePreview();$('#entry-form').addEventListener('input',()=>{dirty=true;updatePreview()});$('#entry-form').addEventListener('change',()=>{dirty=true;updatePreview()});$('#entry-form').addEventListener('submit',saveEntry)}if(tab==='backup'&&pending)showImport();}\nfunction leave(){return !dirty||confirm('Ungespeicherte Änderungen verwerfen? Mit „Abbrechen“ bleibst du in der Eingabe.')}\nasync function navigate(t,m){if(!leave())return;dirty=false;pending=null;importData=null;if(m)editing=m;tab=t;render();window.scrollTo(0,0)}\nasync function change(updater,label){state=await commit(state.revision,updater,label);channel?.postMessage({revision:state.revision});rows=C.calculate(state.records)}\nasync function saveEntry(e){e.preventDefault();try{const r=gather();await change(s=>{s.records=[...s.records.filter(x=>x.month!==r.month),r].sort((a,b)=>a.month.localeCompare(b.month))},`${C.monthLabel(r.month)} gespeichert`);dirty=false;render();notify('Monat lokal gespeichert. Auswertungen sind aktualisiert.')}catch(e){error(e)}}\nlet channel;try{channel=new BroadcastChannel('energie-monitor:'+new URL('.',import.meta.url).pathname);channel.onmessage=async()=>{notify('Daten wurden in einem anderen Fenster geändert.');if(!dirty&&!pending){state=await readState();render()}}}catch{}\nwindow.addEventListener('focus',async()=>{if(state&&!dirty&&!pending){const fresh=await readState();if(fresh.revision!==state.revision){state=fresh;render()}}});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});\ndocument.addEventListener('change',async e=>{try{const id=e.target.id;if(id==='year'){year=e.target.value;render()}if(id==='analysis'){analysis=e.target.value;render()}if(id==='metric'){metric=e.target.value;render()}if(id==='year-b'){yearB=e.target.value;render()}if(id==='calendar-month'){calendarMonth=+e.target.value;render()}if(id==='import-file'&&e.target.files[0])await importFile(e.target.files[0]);if(id==='import-sheet'||id==='header-row')showMapping();}catch(e){error(e)}});\ndocument.addEventListener('input',e=>{if(e.target.id==='history-search')$('#month-list').innerHTML=historyList(e.target.value)});\ndocument.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest('[data-tip]')){e.preventDefault();showTip(e.target.closest('[data-tip]'))}});\nfunction showTip(el){el.closest('.chart-wrap').querySelector('.chart-value').textContent=el.dataset.tip}\ndocument.addEventListener('click',async e=>{const el=e.target.closest('button,[data-tip]');if(!el)return;try{\n if(el.dataset.tip){showTip(el);return}if(el.dataset.nav){await navigate(el.dataset.nav);return}if(el.dataset.edit){await navigate('entry',el.dataset.edit);return}\n if(el.id==='load-month'){const m=$('#pick-month').value;if(!C.validMonth(m))throw Error('Bitte einen gültigen Monat ab 1900 wählen.');await navigate('entry',m)}\n if(el.id==='discard'){if(leave()){state=await readState();dirty=false;render()}}\n if(el.id==='draft'){const r=gather();const draft=C.initialState();draft.records=[r];download(new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),`Energie-Entwurf-${r.month}.json`)}\n if(el.id==='delete-month'&&confirm(`${C.monthLabel(editing)} wirklich löschen? Wiederherstellung ist anschließend unter „Sichern“ möglich.`)){await change(s=>s.records=s.records.filter(r=>r.month!==editing),`${C.monthLabel(editing)} gelöscht`);dirty=false;render();notify('Monat gelöscht. Wiederherstellung unter Sichern möglich.')}\n if(el.dataset.restore!=null&&confirm('Daten, Einstellungen und Quellhinweise auf diesen früheren Stand zurücksetzen? Der aktuelle Stand wird davor gesichert.')){const snap=C.clone(state.history[+el.dataset.restore].snapshot);await change(s=>Object.assign(s,snap),'Früheren Stand wiederhergestellt');render();notify('Früherer Stand lokal wiederhergestellt.')}\n if(el.dataset.export){el.disabled=true;await doExport(el.dataset.export);el.disabled=false}\n if(el.id==='persist'){const ok=await navigator.storage?.persist?.();notify(ok?'Dauerhafter Speicher wurde gewährt. JSON-Sicherungen bleiben wichtig.':'Dauerhafter Speicher nicht gewährt oder nicht unterstützt. Bitte regelmäßig JSON sichern.')}\n if(el.id==='save-settings'){const n=Number($('#backup-days').value);if(!Number.isInteger(n)||n<1||n>365)throw Error('Bitte 1 bis 365 Tage eingeben.');await change(s=>s.settings.backupDays=n,'Sicherungshinweis geändert');notify('Einstellung gespeichert.')}\n if(el.id==='check-update'){const reg=await navigator.serviceWorker?.getRegistration();if(reg){await reg.update();notify(reg.waiting?'Update bereit. Alle App-Fenster schließen und neu öffnen.':'Update-Prüfung abgeschlossen.')}else throw Error('Service Worker noch nicht eingerichtet.')}\n if(el.id==='map-preview'){const sheet=selectedSheet();const mapping=Object.fromEntries($$('[data-map]').map(x=>[x.dataset.map,x.value]));pending={records:IO.mappedRecords(sheet.rows,+$('#header-row').value-1,mapping),metadata:{sourceName:importData.name},full:false};showImport()}\n if(el.id==='cancel-import'){pending=null;importData=null;$('#import-area').innerHTML='';$('#import-file').value='';$('#import-error').hidden=true;notify('Import abgebrochen. Datenbestand unverändert.')}\n if(el.id==='apply-import')await applyImport();\n }catch(e){el.disabled=false;error(e)}});\nfunction download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}\nasync function doExport(kind){const from=$('#export-from').value,to=$('#export-to').value;if(from&&to&&from>to)throw Error('Der Beginn liegt nach dem Ende.');let data,mime;if(kind==='json'){data=JSON.stringify(state,null,2);mime='application/json'}if(kind==='csv'){data=IO.exportCSV(state.records.filter(r=>(!from||r.month>=from)&&(!to||r.month<=to)));mime='text/csv;charset=utf-8'}if(kind==='xlsx'){data=await IO.exportXLSX(state,from,to);mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}const name=`Energie-${kind==='json'?'Sicherung':'Auswertung'}-${new Date().toLocaleDateString('sv-SE')}.${kind}`;const file=new File([data],name,{type:mime});if(backupURL)URL.revokeObjectURL(backupURL);backupURL=URL.createObjectURL(file);$('#download-area').innerHTML=`<div class=\"warn\"><strong>Datei fertig.</strong> Wähle jetzt, wo du sie sichern möchtest.<div class=\"row\" style=\"margin-top:12px\"><a href=\"${backupURL}\" download=\"${name}\">Datei herunterladen</a><button id=\"share-export\">Teilen / in Dateien sichern</button></div><small>Im Systemdialog „In Dateien sichern“ → „Auf meinem iPhone“ wählen.</small></div>`;$('#share-export').onclick=async()=>{try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:name});else download(file,name)}catch(e){if(e.name!=='AbortError')error(e)}};if(kind==='json')await change(s=>s.settings.lastBackup=new Date().toISOString(),null);notify('Export erstellt. Jetzt herunterladen oder in Dateien sichern.')}\nasync function importFile(file){pending=null;importData=null;$('#import-error').hidden=true;$('#import-area').innerHTML='<p class=\"section\">Datei wird lokal geprüft …</p>';if(file.size>30*1024*1024)throw Error('Datei zu groß. Bitte höchstens 30 MB importieren.');try{let parsed;if(/\\.json$/i.test(file.name)){const b=C.validateBackup(JSON.parse(await file.text()));pending={...b,full:true};showImport();return}else if(/\\.xlsx$/i.test(file.name))parsed=await IO.readXLSX(await file.arrayBuffer());else if(/\\.csv$/i.test(file.name))parsed=IO.readCSV(await file.text());else throw Error('Unterstützt werden XLSX, CSV und JSON.');if(parsed.known){pending={records:parsed.records,metadata:parsed.metadata,full:false};showImport()}else{importData={...parsed,name:file.name};showMapping(true)}}catch(e){$('#import-area').innerHTML='';throw e}}\nfunction selectedSheet(){return importData.sheets[+($('#import-sheet')?.value||0)]}\nfunction showMapping(initial=false){const index=+($('#import-sheet')?.value||0),header=initial?1:+($('#header-row')?.value||1),sheet=importData.sheets[index];const headers=sheet.rows[header-1]||[];$('#import-area').innerHTML=`<div class=\"section\"><h3>Spalten zuordnen</h3><p class=\"muted\">Zählerstände und Monatsmengen ausdrücklich unterscheiden. Nur Gas in m³ und Strom in kWh zuordnen. Andere Einheiten vor dem Import umrechnen.</p><div class=\"row\"><label class=\"grow\">Tabellenblatt<select id=\"import-sheet\">${opts(importData.sheets.map((s,i)=>[i,s.name]),index)}</select></label><label>Kopfzeile<input id=\"header-row\" type=\"number\" min=\"1\" max=\"${sheet.rows.length}\" value=\"${header}\"></label></div><details><summary>Erste Datenzeilen ansehen</summary><pre>${esc(JSON.stringify(sheet.rows.slice(header-1,header+3),null,2))}</pre></details><div class=\"mapping\">${Object.entries(IO.MAP_FIELDS).map(([k,label])=>`<label>${label}<select data-map=\"${k}\">${opts([['','Nicht zugeordnet'],...headers.map((h,i)=>[i,`${i+1}: ${h??'(leer)'}`])],'')}</select></label>`).join('')}</div><div class=\"row section\"><button class=\"primary\" id=\"map-preview\">Importvorschau prüfen</button><button id=\"cancel-import\">Abbrechen</button></div></div>`}\nfunction showImport(){if(!pending)return;const summary={};pending.records.forEach(r=>{const type=C.conflictType(state.records.find(t=>t.month===r.month),r);summary[type]=(summary[type]||0)+1});$('#import-area').innerHTML=`<div class=\"section\"><h3>Vorschau · ${pending.records.length} Monate</h3><p>${Object.entries(summary).map(([k,n])=>`${n} ${k}`).join(' · ')}</p><p class=\"muted\">Zusammenführen ergänzt nur leere Messwerte. Vorhandene Zahlen bleiben erhalten. Ersetzen übernimmt den ausgewählten Monat vollständig. Alle Änderungen werden gemeinsam gespeichert.</p>${pending.full?`<label class=\"checklabel\"><input id=\"full-restore\" type=\"checkbox\"> Vollständige JSON-Wiederherstellung: gesamten Bestand, Einstellungen, Metadaten und Historie ersetzen</label><p class=\"muted\">Davor wird eine lokale Kopie des aktuellen Stands angelegt. Die Auswahl unten gilt nur beim Zusammenführen.</p>`:''}<details><summary>Alle Monate und Importentscheidungen anzeigen</summary>${pending.records.map(r=>{const a=state.records.find(t=>t.month===r.month);return `<div class=\"import-row\"><div class=\"row between\"><strong>${C.monthLabel(r.month)}</strong><span class=\"pill\">${C.conflictType(a,r)}</span><select aria-label=\"Importentscheidung ${r.month}\" data-choice=\"${r.month}\">${opts([['merge','Zusammenführen'],['skip','Überspringen'],['replace','Diesen Monat ersetzen']],'merge')}</select></div><div class=\"data-table\">${C.KEYS.map(k=>`<div class=\"data-row\"><span>${C.METRICS[k][0]} · ${C.METRICS[k][1]}</span><span>${a?`Vorhanden: ${fmt(a[k].reading)} Stand / ${fmt(a[k].amount)} Menge<br>`:''}Import: ${fmt(r[k].reading)} Stand / ${fmt(r[k].amount)} Menge${r[k].quality==='estimated'?' ≈':''}</span></div>`).join('')}</div><details><summary>Notizen & Qualität</summary><p>${esc(r.note)}<br>${C.KEYS.map(k=>`${C.METRICS[k][0]}: ${esc(r[k].quality)}\\n${esc(r[k].note)}`).join('\\n\\n')}</p></details></div>`}).join('')}</details><div class=\"row section\"><button id=\"apply-import\" class=\"primary\">Import jetzt lokal übernehmen</button><button id=\"cancel-import\">Abbrechen</button></div></div>`}\nasync function applyImport(){const full=$('#full-restore')?.checked;const choices=Object.fromEntries($$('[data-choice]').map(x=>[x.dataset.choice,x.value]));if((full||Object.values(choices).includes('replace'))&&!confirm('Die gewählten vorhandenen Daten wirklich ersetzen? Ein lokaler Wiederherstellungspunkt wird angelegt.'))return;const candidate=C.clone(pending);await change(s=>{if(full){s.records=candidate.records;s.settings=candidate.settings;s.metadata=candidate.metadata;s.history=candidate.history}else{s.records=C.mergeRecords(s.records,candidate.records,choices);s.metadata.sourceSheets={...s.metadata.sourceSheets,...candidate.metadata?.sourceSheets};s.metadata.lastImport=new Date().toISOString()}},full?'JSON-Sicherung wiederhergestellt':'Import übernommen');pending=null;importData=null;render();notify('Import vollständig und lokal gespeichert.')}\nasync function offline(){if(!('serviceWorker'in navigator)){swStatus='Offline-Modus in diesem Browser nicht unterstützt.';return}try{const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./'});await navigator.serviceWorker.ready;swStatus='✓ Offline-Paket vollständig eingerichtet. Nach dem ersten Neuladen auch ohne Internet startbar.';if(reg.waiting)swStatus+=' Update wartet: alle App-Fenster schließen und neu öffnen.';reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){swStatus='Update bereit. Alle App-Fenster schließen und neu öffnen.';if($('#offline-status'))$('#offline-status').textContent=swStatus}})});if($('#offline-status'))$('#offline-status').textContent=swStatus}catch{swStatus='Offline-Einrichtung fehlgeschlagen. HTTPS und vollständiges Upload-Paket prüfen.';if($('#offline-status'))$('#offline-status').textContent=swStatus}}\ntry{state=await readState();if(state.records.length){const yy=years();if(!state.records.some(r=>r.month.startsWith(year)))year=yy.find(y=>state.records.some(r=>r.month.startsWith(y)))||year;yearB=String(+year-1)}render();offline()}catch(e){$('#app').innerHTML=`<div class=\"warn error\">${esc(e.message)}<br>Es wurden keine Daten verändert. Die App benötigt verfügbaren lokalen Browserspeicher.</div>`}\n";
