self.addEventListener('install',event=>event.waitUntil((async()=>{
 try{
  const cache=await caches.open(CACHE);
  await cache.addAll(FILES.map(path=>new Request(new URL(path,self.registration.scope),{cache:'reload'})));
  await cache.put(new URL('./app.js',self.registration.scope),new Response(UPDATED_APP,{headers:{'Content-Type':'text/javascript; charset=utf-8'}}));
  await cache.put(new URL('./styles.css',self.registration.scope),new Response(UPDATED_CSS,{headers:{'Content-Type':'text/css; charset=utf-8'}}));
  await self.skipWaiting();
 }catch(error){await caches.delete(CACHE);throw error;}
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 await self.clients.claim();
 const keys=await caches.keys();
 await Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)));
})()));
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);
 if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;
 event.respondWith((async()=>{
  const cache=await caches.open(CACHE);
  const hit=await cache.match(event.request,{ignoreSearch:true});
  if(hit)return hit;
  if(event.request.mode==='navigate')return cache.match(new URL('./index.html',self.registration.scope));
  return fetch(event.request);
 })());
});
